const rawText = $input.first().json.content.parts[0].text;
const cleanText = rawText.replace(/```json|```/g, '').trim();
return JSON.parse(cleanText);

const inputItem = $input.first();
let rawText = inputItem.json.text || (inputItem.json.content && inputItem.json.content.parts ? inputItem.json.content.parts[0].text : "") || "";

// 1. Nettoyage JSON et Markdown
rawText = rawText.replace(/```json/g, "").replace(/```/g, "").trim();

let subject = "Suivi de notre échange"; 
let bodyContent = rawText;

try {
    const parsed = JSON.parse(rawText);
    if (parsed.Objet) subject = parsed.Objet;
    if (parsed.Corps) bodyContent = parsed.Corps;
} catch (e) {}

// --- CONVERSION AVANCÉE ---
function formatEmailHtml(text) {
    return text
        // Nettoyage des titres Markdown (### Titre -> Gras aéré)
        .replace(/^#+\s+(.*)$/gm, '<div style="margin-top: 15px; margin-bottom: 5px;"><b>$1</b></div>')

        // Gras standard
        .replace(/\*\*(.*?)\*\*/g, '<b>$1</b>')

        // Liens
        .replace(/\[(.*?)\]\((.*?)\)/g, '<a href="$2" style="color: #007BFF; text-decoration: underline;">$1</a>')

        // Listes à puces (groupées sans trop d'espace entre elles)
        .replace(/^\s*[\-\*]\s+(.*)$/gm, '<div style="margin-left: 15px; margin-bottom: 2px;">• $1</div>')

        // Gestion des paragraphes (Double saut de ligne -> Bloc avec marge)
        .split(/\n\n+/).map(para => {
            if (para.includes('<div')) return para; // Ne pas toucher si c'est déjà formaté
            return `<div style="margin-bottom: 12px;">${para.replace(/\n/g, "<br>")}</div>`;
        }).join("");
}

subject = subject.replace(/[#\*]/g, ""); // Nettoyer le sujet
const htmlBody = formatEmailHtml(bodyContent);

const finalHtml = `
<div style="font-family: 'Segoe UI', Arial, sans-serif; font-size: 16px; line-height: 1.5; color: #1a1a1a; max-width: 600px; margin: 0 auto;">
    ${htmlBody}
    <div style="margin-top: 30px; padding-top: 15px; border-top: 1px solid #eee; color: #666; font-size: 14px;">
        Bien cordialement,<br>
        <strong>L'équipe Educfinance</strong>
    </div>
</div>
`;

return { json: { email_subject: subject, email_body: finalHtml } };

// ========================================
// FORMATAGE PROFIL POUR PIPEDRIVE
// ========================================

// 1. RÉCUPÉRATION DES DONNÉES
const profiling = $('Parsing variables du profiling').item.json;
const scoring = $('Mettre en variable le scoring output').item.json;

// 2. EXTRACTION DES VARIABLES PRINCIPALES
const prenom = profiling.identite?.prenom || "Prospect";
const ton = profiling.ton_conversationnel || "Vous";
const source = profiling.identite?.source_acquisition || "Non spécifié";

// Situation personnelle
const statut_familial = profiling.situation_familiale?.statut || "Non spécifié";
const details_famille = profiling.situation_familiale?.details || "";

// Situation professionnelle
const profession = profiling.situation_professionnelle?.profession || "Non spécifié";
const employeur = profiling.situation_professionnelle?.employeur_type || "Non spécifié";
const regime_retraite = profiling.situation_professionnelle?.regime_retraite || "Non spécifié";

// Situation financière
const dettes = profiling.situation_financiere?.dettes || "Non spécifié";
const epargne = profiling.situation_financiere?.epargne_investissements || "Non spécifié";
const niveau_connaissance = profiling.situation_financiere?.niveau_connaissance || "Non spécifié";

// Objectifs
const objectif_principal = profiling.objectifs_projets?.objectif_principal || "Non spécifié";
const court_terme = profiling.objectifs_projets?.court_terme || "Non spécifié";
const long_term = profiling.objectifs_projets?.moyen_long_terme || "Non spécifié"; // <-- CORRECTION ICI

// Logistique
const cohorte = profiling.logistique?.dates_souhaitees || "Non spécifié";
const date_rappel = profiling.logistique?.date_rappel || "Non spécifié";
const accompagnement = profiling.logistique?.accompagnement || "Non spécifié";
const contraintes = profiling.logistique?.contraintes || "Non spécifié";

// Notes spéciales
const notes_perso = profiling.notes_personnalisation || "Aucune note particulière";

// Scoring (Utilisation des nouvelles clés)
const score_global = scoring?.score_qualite_profil || "N/A";
const probabilite = scoring?.probabilite_closing_immediat || "N/A";
const next_action = scoring?.analyse_expert?.conseil_closing || "À définir";

// Définition de la catégorie et des couleurs (Gardé pour les Custom Fields)
const scoreValue = parseFloat(score_global);
let categorie = "COLD";
let couleurFond = "#6b7280"; // Gris
let couleurTexte = "#000000"; // Noir

if (scoreValue >= 8) {
    categorie = "HOT";
    couleurFond = "#10b981"; // Vert
} else if (scoreValue >= 5) {
    categorie = "WARM";
    couleurFond = "#f59e0b"; // Orange
} else if (scoreValue > 0) {
    categorie = "LUKEWARM";
    couleurFond = "#ef4444"; // Rouge
}

// 3. CONSTRUCTION DE LA NOTE HTML ENRICHIE (SANS LE BLOC SCORE)
let noteHtml = `
<div style="font-family: Arial, sans-serif; line-height: 1.4; font-size: 14px; color: #333333;">

<div style="background: #007BFF; color: white; padding: 12px; border-radius: 6px; margin-bottom: 10px;">
  <h2 style="margin: 0; font-size: 16px;">📋 PROFIL PROSPECT - ${prenom.toUpperCase()}</h2>
  <p style="margin: 5px 0 0 0; font-size: 12px;">Ton: ${ton} • Source: ${source}</p>
</div>

<!-- BLOC SCORE SUPPRIMÉ ICI - IL SERA AJOUTÉ PAR L'IA EN HAUT -->

<div style="background: #FFFFFF; padding: 12px; border-left: 4px solid #007BFF; margin-bottom: 10px;">
  <h3 style="margin-top: 0; font-size: 14px; color: #000000;">👤 IDENTITÉ & SITUATION</h3>
  <p style="margin-bottom: 5px;"><strong>Familial:</strong> ${statut_familial}${details_famille ? ' - ' + details_famille : ''}</p>
  <p style="margin-bottom: 0;"><strong>Professionnel:</strong> ${profession} (${employeur})</p>
  ${regime_retraite !== "Non spécifié" ? `<p style="margin-top: 5px;"><strong>Retraite:</strong> ${regime_retraite}</p>` : ''}
</div>

<div style="background: #FFFFFF; padding: 12px; border-left: 4px solid #10b981; margin-bottom: 10px;">
  <h3 style="margin-top: 0; font-size: 14px; color: #000000;">💰 SITUATION FINANCIÈRE</h3>
  <p style="margin-bottom: 5px;"><strong>Dettes:</strong> ${dettes}</p>
  <p style="margin-bottom: 5px;"><strong>Épargne/Investissements:</strong> ${epargne}</p>
  <p style="margin-bottom: 0;"><strong>Niveau de connaissance:</strong> ${niveau_connaissance}</p>
</div>

<div style="background: #FFFFFF; padding: 12px; border-left: 4px solid #8b5cf6; margin-bottom: 10px;">
  <h3 style="margin-top: 0; font-size: 14px; color: #000000;">🎯 OBJECTIFS</h3>
  <p style="margin-bottom: 5px;"><strong>Principal:</strong> ${objectif_principal}</p>
  <p style="margin-bottom: 5px;"><strong>Court terme:</strong> ${court_terme}</p>
  <p style="margin-bottom: 0;"><strong>Moyen/Long terme:</strong> ${long_term}</p>
</div>

<div style="background: #FFF0F0; padding: 12px; border-left: 4px solid #CC0000; margin-bottom: 10px;">
  <h3 style="margin-top: 0; font-size: 14px; color: #CC0000;">🔥 POINTS DOULOUREUX</h3>
  <ul style="margin: 0; padding-left: 20px; margin-top: 5px;">`;

if (profiling.points_douloureux && profiling.points_douloureux.length > 0) {
  profiling.points_douloureux.forEach(pain => {
    noteHtml += `<li style="margin-bottom: 3px;">${pain}</li>`;
  });
} else {
  noteHtml += `<li>Aucun point douloureux identifié</li>`;
}

noteHtml += `</ul>
</div>

<div style="background: #FFFFFF; padding: 12px; border-left: 4px solid #10b981; margin-bottom: 10px;">
  <h3 style="margin-top: 0; font-size: 14px; color: #000000;">✨ ATTENTES FORMATION</h3>
  <p style="margin-bottom: 5px;"><strong>Vision:</strong> ${profiling.attentes_formation?.vision_ultime || "Non spécifié"}</p>
  <p style="margin-bottom: 0;"><strong>Besoins:</strong> ${profiling.attentes_formation?.besoins_specifiques || "Non spécifié"}</p>
</div>

<div style="background: #FFFFFF; padding: 12px; border-left: 4px solid #f59e0b; margin-bottom: 10px;">
  <h3 style="margin-top: 0; font-size: 14px; color: #000000;">📅 LOGISTIQUE</h3>
  <p style="margin-bottom: 5px;"><strong>Cohorte souhaitée:</strong> ${cohorte}</p>
  ${date_rappel !== "Non spécifié" ? `<p style="margin-bottom: 5px;"><strong>📞 Rappel prévu:</strong> ${date_rappel}</p>` : ''}
  ${accompagnement !== "Non spécifié" ? `<p style="margin-bottom: 5px;"><strong>Accompagnement:</strong> ${accompagnement}</p>` : ''}
  ${contraintes !== "Non spécifié" ? `<p style="margin-bottom: 0;"><strong>Contraintes:</strong> ${contraintes}</p>` : ''}
</div>

<div style="background: #FFFFFF; padding: 12px; border-left: 4px solid #3b82f6; margin-bottom: 10px;">
  <h3 style="margin-top: 0; font-size: 14px; color: #000000;">📋 PROCHAINES ÉTAPES</h3>
  <ol style="margin: 0; padding-left: 20px; margin-top: 5px;">`;

if (profiling.next_steps && profiling.next_steps.length > 0) {
  profiling.next_steps.forEach(step => {
    noteHtml += `<li style="margin-bottom: 3px;">${step}</li>`;
  });
} else {
  noteHtml += `<li>Aucune étape définie</li>`;
}

noteHtml += `</ol>
  <div style="background: #dbeafe; padding: 10px; border-radius: 4px; margin-top: 10px;">
    <strong>🎯 ACTION PRIORITAIRE:</strong> ${next_action}
  </div>
</div>`;

if (notes_perso !== "Aucune note particulière") {
  noteHtml += `<div style="background: #fef3c7; padding: 12px; border-left: 4px solid #f59e0b; margin-bottom: 10px;">
  <h3 style="margin-top: 0; font-size: 14px; color: #92400e;">💡 NOTES DE PERSONNALISATION</h3>
  <p style="margin-bottom: 0;">${notes_perso}</p>
</div>`;
}

noteHtml += `<div style="background: #f3f4f6; padding: 10px; border-radius: 6px; text-align: center; font-size: 12px; color: #6b7280; margin-top: 10px;">
  Profil généré automatiquement • Analysé par <strong>Djamel</strong> • ${new Date().toLocaleDateString('fr-CA')}
</div>

</div>`;

// 4. PRÉPARATION DES CUSTOM FIELDS PIPEDRIVE
const customFields = {
  "Ton conversationnel": ton,
  "Source acquisition": source,
  "Score Lead": score_global,
  "Catégorie Lead": categorie,
  "Probabilité conversion": probabilite,
  "Statut familial": statut_familial,
  "Profession": profession,
  "Type employeur": employeur,
  "Niveau dette": dettes,
  "Niveau épargne": epargne,
  "Connaissance finance": niveau_connaissance,
  "Objectif principal": objectif_principal,
  "Cohorte préférée": cohorte,
  "Date rappel": date_rappel,
  "Contraintes logistiques": contraintes,
  "Next Best Action": next_action
};

// 5. RETOUR STRUCTURÉ - CRÉER UN NOUVEL OBJET
return [{
  json: {
    pipedrive_note: noteHtml, // Le HTML du profil détaillé (Bloc 1)
    prospect_name: prenom,
    prospect_full_name: `${prenom} - ${profession}`,
    custom_fields: customFields,
    metadata: {
      score: score_global,
      category: categorie,
      probability: probabilite,
      ton: ton,
      next_action: next_action,
      date_profiling: new Date().toISOString()
    },
    email_data: {
      prenom: prenom,
      ton: ton,
      objectif_principal: objectif_principal,
      douleur_principale: profiling.points_douloureux?.[0] || "préoccupations financières",
      next_step: profiling.next_steps?.[0] || "prendre rendez-vous"
    }
  }
}];

// On récupère l'objet JSON du nœud précédent
const input = $node["Stratégie de Relance"].json;
let rawText = "";

// On cherche le texte dans la structure spécifique de Gemini/Google AI
if (input.content && input.content.parts && input.content.parts[0]) {
    rawText = input.content.parts[0].text;
} else if (input.text) {
    rawText = input.text;
}

try {
    // Nettoyage : on cherche le premier '{' et le dernier '}' pour isoler le JSON
    const start = rawText.indexOf('{');
    const end = rawText.lastIndexOf('}');

    if (start === -1 || end === -1) throw new Error("Pas de JSON trouvé");

    const jsonString = rawText.substring(start, end + 1);
    const data = JSON.parse(jsonString);

    return {
        date_action: data.date_action,
        sujet_action: data.sujet_action,
        explication: data.explication,
        type_action: data.type_action || 'email'
    };
} catch (e) {
    // En cas d'erreur, on renvoie des données par défaut pour ne pas bloquer le workflow
    return {
        date_action: new Date().toISOString().split('T')[0],
        sujet_action: "⚠️ Erreur de formatage IA",
        explication: "L'IA n'a pas renvoyé un JSON valide. Texte brut : " + rawText,
        type_action: "email"
    };
}

